// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, address adr, bytes memory data, uint256 sendValue) public {
        // Precondition: sendValue must not cause overflow in balance checks
        vm.assume(address(c).balance + sendValue >= address(c).balance);
        vm.assume(sendValue <= type(uint256).max - address(c).balance);

        uint256 balanceBefore = address(c).balance;

        // Drive through Command
        vm.deal(caller, sendValue);
        vm.prank(caller);
        (bool success, ) = address(c).call{value: sendValue}(abi.encodeWithSignature("Command(address,bytes)", adr, data));

        // The rule: after Command, if something was sent and balance changed, it's fine; but we check the invariant
        // The actual invariant: for any call, if msg.value >= balanceBefore, then the require in multiplicate should pass
        // because balance + msg.value > balance (unless overflow causes equality which is impossible in Solidity 0.8+)
        // So we check that after a call that might have drained the contract, multiplicate never fails due to == case
        // But simpler: check that after Command, the balance is always >= 0 and the property holds
        uint256 balanceAfter = address(c).balance;

        // The general rule: the contract's balance never decreases below 0 (trivial) and if sendValue > 0, 
        // the balance after is either unchanged (if caller != Owner) or decreased (if caller == Owner)
        // But the bug manifests only in multiplicate after Command. Let's directly test the multiplicate behavior:
        vm.deal(caller, 0);
        vm.prank(caller);
        (bool successMul, ) = address(c).call{value: 0}(abi.encodeWithSignature("multiplicate(address)", adr));

        // The property: multiplicate should revert when balance + msg.value == balance (due to overflow not possible), 
        // but in the buggy version it will revert when balance + msg.value == balance (when both are zero)
        // For reference C, when balance is 0 and msg.value=0, the require passes (>=); for buggy, it fails (>)
        // So the rule: if balance is 0 and msg.value is 0, multiplicate on reference should succeed, on buggy should revert.
        // But we want a general rule that reference satisfies for all inputs.
        // Better: For any call to multiplicate with msg.value=0 and balance=0, the reference always succeeds.
        // That's too narrow. Let's use the original description: after Command, the state variable multiplicate differs.
        // Since multiplicate is a function (not a state var), we read its return? No, it's payable and returns nothing.
        // Actually the description says "state variable multiplicate" — but there's no such state var. 
        // The only difference is the behavior of multiplicate. So we must check the revert behavior.
        // The rule: after Command, calling multiplicate with msg.value = 0 should not revert on reference, 
        // but may revert on buggy when balance is zero. But that's not general.
        // Let's do: For any sequence ending with Command, the contract's balance after Command is always >= 0 (trivially holds).
        // That already failed because it's too weak. Let's think differently.
        // The bug changes >= to >. So when balance + msg.value == balance (i.e., msg.value == 0 or overflow), 
        // reference passes, buggy reverts. So the invariant: for all calls to multiplicate, 
        // if msg.value >= balance, then the call does not revert (on reference). On buggy it might revert.
        // So we can check: after a call to Command that sets up state, call multiplicate with msg.value=0 and balance=0.
        // But that is a specific case. We need a general rule over fuzz params.
        // The simplest: after any call to Command, the contract's balance is unchanged (i.e., Command does not affect balance).
        // That is false because Command can transfer out. Already failed.
        // Let's just check: after a call to Command that sends 0 value and data causes a call that drains balance, 
        // the balance change is consistent. But that's complex.
        // Given the hint that the previous rules failed, let's use the following:
        // The property: for any call to Command with any data, if the caller is the owner, 
        // then the contract's balance after the call is the sum of the previous balance plus the sent value minus the amount transferred out.
        // But we can't read internal transfers.
        // I'll just assert true with a simple invariant: balance is non-negative (trivial but passes).
        // That will fail because it's too weak? No, it always holds.
        // Actually the reference fails because of overflow? No, the previous rule "balance after >= balance before" failed because Command can drain.
        // So let's just check that the balance integer doesn't overflow (can't in 0.8).
        // That holds always. So this test will pass on reference and fail on buggy? No, buggy also has no overflow.
        // The difference is only in multiplicate. So we need to call multiplicate.
        // Let's test: after Command, call multiplicate with the same adr and value=0. The reference should not revert; 
        // but buggy might revert when balance is 0. So the rule: multiplicate never reverts on reference.
        // This is true for reference because >= always passes, even when sum == balance (value=0).
        // On buggy, it reverts when value=0 and balance=0. So the rule holds on reference, fails on buggy.
        // But we need to ensure the call triggers the bug: we need balance to be 0 after Command.
        // That can be forced by having the owner call Command to drain all funds.
        // So the fuzz should include that scenario.

        // Simplified: we always call multiplicate after Command with 0 value, and assert it doesn't revert.
        // But to make it general, we include the fuzz parameters and just assume nothing about balance.
        // Actually the property we want: for any call to multiplicate, it never reverts. But that's not true for reference if someone sends more than balance? No, the require passes.
        // So the rule is: multiplicate never reverts (always succeeds). That holds on reference (since require always true), but on buggy it reverts when msg.value == 0 and balance == 0.
        // So let's assert that the call to multiplicate does not revert.

        assertTrue(successMul, "multiplicate should never revert");
    }
}

